--
-- Name: arabic_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.arabic_normalize(input text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT trim(regexp_replace(
    regexp_replace(
      translate(lower(normalize(coalesce(input, ''), NFKC)),
        'أإآىیک٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹ـ',
        'اااييك01234567890123456789'),
      '[ً-ٰٟۖ-ۭ]', '', 'g'),
    '[^[:alnum:]]+', ' ', 'g'));
$$;


